Rules.InvariantScript:
/*With(
    {
        _txt: Trim(candidate),
        _isEnglish: Lower(First(Split(Language(), "-")).Value) = "en"
    },
    If(
        _isEnglish,
        IsMatch(
            _txt,
            "[0-9]+([,][0-9]+)*([.]0+)?",
            MatchOptions.Complete
        ),
        IsMatch(
            _txt,
            "[0-9]+([.][0-9]+)*(,0+)?",
            MatchOptions.Complete
        )
    )
)*/
With(
    {
        _txt: Trim(candidate),
        _isEnglish: Lower(First(Split(Language(), "-")).Value) = "en"
    },
    If(
        IsBlank(_txt),
        false,
        If(
            _isEnglish,
            IsMatch(
                _txt,
                "^[+-]?\d+(,\d+)*$",
                MatchOptions.Complete
            ),
            IsMatch(
                _txt,
                "^[+-]?\d+(\.\d+)*$",
                MatchOptions.Complete
            )
        )
    )
)

With(
    {
        _txt: Trim(candidate),
        _isEnglish: Lower(First(Split(Language(), "-")).Value) = "en"
    },
    If(
        IsBlank(_txt),
        false,
        With(
            {
                _isValidNumber: If(
                    _isEnglish,
                    IsMatch(
                        _txt,
                        "^[+-]?\d+(,\d+)*(\.\d+)?$",
                        MatchOptions.Complete
                    ),
                    IsMatch(
                        _txt,
                        "^[+-]?\d+(\.\d+)*(,\d+)?$",
                        MatchOptions.Complete
                    )
                ),
                _normalizedNumberText: If(
                    _isEnglish,
                    Substitute(_txt, ",", ""),
                    Substitute(
                        Substitute(_txt, ".", ""),
                        ",",
                        "."
                    )
                )
            },
            IfError(
                And(
                    _isValidNumber,
                    Value(_normalizedNumberText, "en-US") >= min,
                    Value(_normalizedNumberText, "en-US") <= max
                ),
                false
            )
        )
    )
)

With(
    {
        varLang: Lower(
            First(
                Split(
                    Language(),
                    "-"
                )
            ).Value
        )
    },
    Switch(
        varLang,
        "en",
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\.\d{0,1})?$"
        ),
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\,\d{0,1})?$"
        )
    )
)

