With(
    {
        startDate: candidate,
        yearsToAdd: Value(addition),
        wholeYears: RoundDown(
            Value(addition),
            0
        ),
        fractionalYears: Value(addition) - RoundDown(
            Value(addition),
            0
        )
    },
    With(
        {
            monthsToAdd: RoundDown(
                fractionalYears * 12,
                0
            ),
            remainingFraction: (fractionalYears * 12) - RoundDown(
                fractionalYears * 12,
                0
            )
        },
        With(
            {
                dateAfterYearsAndMonths: DateAdd(
                    DateAdd(
                        candidate,
                        wholeYears,
                        TimeUnit.Years
                    ),
                    monthsToAdd,
                    TimeUnit.Months
                )
            },
            With(
                {
                    daysInMonth: Day(
                        DateAdd(
                            DateAdd(
                                dateAfterYearsAndMonths,
                                1,
                                TimeUnit.Months
                            ),
                            -1,
                            TimeUnit.Days
                        )
                    )
                },
                With(
                    {
                        daysToAdd: Round(
                            remainingFraction * daysInMonth,
                            0
                        )
                    },
                    DateAdd(
                        dateAfterYearsAndMonths,
                        daysToAdd,
                        TimeUnit.Days
                    )
                )
            )
        )
    )
)

