Rules.InvariantScript:
With(
    {
        varSumEntities: Sum(
            colShareholdingEntities,
            'Ownership [%]'
        )
    },
    If(
        And(
            varSumEntities >= 1,
            IsBlank(locShareholdingEntity.'Shareholder Entitiy Type')
        ),
        false,
        true
    )
)

With(
    {
        varSumEntities: Sum(
            colShareholdingEntities,
            'Ownership [%]'
        ),
        varSumEntitiesPercent: Round(
            (1 - (Sum(
                colShareholdingEntities,
                'Ownership [%]'
            ) - locShareholdingEntity.'Ownership [%]')),
            4
        ) * 100
    },
    If(
        IsBlank(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text),
        gblAppResx.InputBlank,
        Or(
            Not(fn_Numeric_GD.IsInteger(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text)),
            Not(fn_Numeric_GD.IsOneDecimal(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text)),
            Not(fn_Numeric_GD.IsTwoDecimal(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text))
        ),
        $"Percentage must be number with two decimal place.",
        And(
            IsNumeric(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text),
            Not(
                fn_Numeric_GD.InRange(
                    txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text,
                    0.1,
                    varSumEntitiesPercent
                )
            )
        ),
        $"The number {txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text} must be between 0 and {Text(
            varSumEntitiesPercent,
            "#0.0#"
        )}.",
        "#Err:"
    )
)

With(
    {
        varSumEntitiesPercent: Round(
            (1 - (Sum(
                colShareholdingEntities,
                'Ownership [%]'
            ) - locShareholdingEntity.'Ownership [%]')),
            4
        ) * 100
    },
    If(
        Or(
            IsBlank(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text),
            Not(IsNumeric(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text))
        ),
        true,
        And(
            Or(
                fn_Numeric_GD.IsInteger(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text),
                fn_Numeric_GD.IsTwoDecimal(txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text)
            ),
            Not(
                fn_Numeric_GD.InRange(
                    txt_GeneralData_RightPanel_ShareholdingEntity_InpForm_BodyForm_Percentage.Text,
                    0.1,
                    varSumEntitiesPercent
                )
            )
        )
    )
)

With(
