                ),
                'Acquisition date': If(
                    drp_GeneralData_DisplayProject_Body_TechnologyTab_Content_ProjectDevelopment.Selected.Value = 'Development Type'.'Acquired Project',
                    dte_GeneralData_DisplayProject_Body_General_Content_Acquisition_Date.SelectedDate,
                    Blank()
                ),
                'Acquisition Price': If(
                    drp_GeneralData_DisplayProject_Body_TechnologyTab_Content_ProjectDevelopment.Selected.Value = 'Development Type'.'Acquired Project',
                    fn_Numeric_With_Separtors_GD.toNumber(txt_GeneralData_DisplayProject_Body_TechnologyTab_Content_AcquisitionPrice.Text),
                    Blank()
                )
            }
        )
    );
    Collect(
        colProcessingSteps,
        "Project data was saved/updated successfully."
    );
    Set(
        gblRecordSelectedProject,
        LookUp(
            Projects,
            ThisRecord.Project = gblRecordSelectedProject.Project
        )
    );
    Set(
        gblRecordSelectedProject,
        Patch(
            Projects,
            gblRecordSelectedProject,
            {
                'Internal Project ID': If(
                    IsBlank(gblRecordSelectedProject.'Internal Project ID'),
                    gblRecordSelectedProject.'Project ID',
                    gblRecordSelectedProject.'Internal Project ID'
                ),
                'Besitzer (Unternehmenseinheit)': Coalesce(
                    drp_GeneralData_DisplayProject_Body_General_Content_Country.Selected.'Business Unit',
                    gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                )
            }
        )
    );
    // =====================================================
    // Start Cluster changed:
    // clean/rebuild approval tracking only AFTER project save
    // =====================================================
    If(
        locGeneralSaveStartClusterChanged,
        Select(btn_General_CancelActiveDraftGateApprovalForStartClusterChange);
        Set(
            gblRecordSelectedProject,
            LookUp(
                Projects,
                ThisRecord.Project = gblRecordSelectedProject.Project
            )
        );
        Collect(
            colProcessingSteps,
            "Project start cluster tracking was refreshed successfully."
        )
    );
    Set(
        gblCurrentUser,
        Patch(
            gblCurrentUser,
            {
                CanEditSelectedProject: And(
                    DataSourceInfo(
                        Projects,
                        DataSourceInfo.CreatePermission
                    ),
                    Coalesce(
                        RecordInfo(
                            gblRecordSelectedProject,
                            RecordInfo.EditPermission
                        ),
                        false
                    )
                )
            }
        )
    );
    Set(
        gblRecordSelectedProjectCountry,
        LookUp(
            Countries,
            Country = gblRecordSelectedProject.Country.Country
        )
    );
    If(
        locNeedShareholdingEntitiesUpdate,
        ClearCollect(
            colShareholdingEntities,
            ForAll(
                colShareholdingEntities As Updated,
                Patch(
                    ShareholderEntityInProjects,
                    If(
                        IsBlank(
                            LookUp(
                                ShareholderEntityInProjects,
                                'Shareholder Entitiy' = Updated.'Shareholder Entitiy'
                            )
                        ),
                        Defaults(ShareholderEntityInProjects),
                        LookUp(
                            ShareholderEntityInProjects,
                            'Shareholder Entitiy' = Updated.'Shareholder Entitiy'
                        )
                    ),
                    {
                        'Shareholder Entitiy Type': Updated.'Shareholder Entitiy Type',
                        Project: gblRecordSelectedProject,
                        'Custom Name': Updated.'Custom Name',
                        'Ownership [%]': Updated.'Ownership [%]',
                        'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                    }
                )
            )
        );
        Collect(
            colProcessingSteps,
            "Project Shareholder Entitiy was saved/updated successfully."
        )
    );
    If(
        locNeedPlantCostsRecalculation,
        ClearCollect(
            colProjectGeneratorsUpdated,
            Patch(
                GeneratorTypeInProjects,
                colProjectGenerators
            )
        );
        Set(
            gblRecordSelectedProject,
            Patch(
                Projects,
                gblRecordSelectedProject,
                {
                    'Plant WTG Cost [EUR]': Sum(
                        colProjectGenerators,
                        'Generators Cost'
                    )
                }
            )
        );
        Collect(
            colProcessingSteps,
            $"Plant WTG Cost (WTG's: {CountIf(
                colProjectGeneratorsUpdated,
                true
            )}), was recalculated and updated successfully."
        )
    );
    // =====================================================
    // Ensure Draft tracking exists.
    // For new/normal projects, Draft starts as In Progress.
    // If cleanup already created it, this block will not overwrite it.
    // =====================================================
    With(
        {
            varSelectedItemProjectStateId: LookUp(
                'Project States',
                ThisRecord.Name = "Draft"
            ).'Project State'
        },
        If(
            IsBlank(
                LookUp(
                    'Project State Trackings',
                    And(
                        Project.Project = gblRecordSelectedProject.Project,
                        'Cluster State'.'Project State' = varSelectedItemProjectStateId
                    )
                )
            ),
            UpdateContext(
                {
                    locRecordDefaultStateTracking: Patch(
                        'Project State Trackings',
                        Defaults('Project State Trackings'),
                        {
                            Project: LookUp(
                                Projects,
                                ThisRecord.Project = gblRecordSelectedProject.Project
                            ),
                            'Cluster State': LookUp(
                                'Project States',
                                ThisRecord.'Project State' = varSelectedItemProjectStateId
                            ),
                            'Approval Comment': Blank(),
                            'Approval Due Date': Blank(),
                            'Approval Cluster State': 'Approval Cluster States'.'In Progress',
                            'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                        }
                    )
                }
            )
        )
    );
    Notify(
        Concat(
            colProcessingSteps,
            $"{Value} {Char(10)}"
        ),
        NotificationType.Success,
        gblAppConstants.DefNotifyTimeoutMilliseconds
    ),
    Notify(
        "Error: Project could not be saved. " & "Internal error: originated on " & FirstError.Source & ". Message: " & FirstError.Message & FirstError.Details.HttpResponse,
        NotificationType.Error
    )
);
Clear(colTemProjectIds);
Refresh(ShareholderEntityInProjects);
ClearCollect(
    colShareholdingEntities,
    Filter(
        ShareholderEntityInProjects,
        ThisRecord.Project.Project = gblRecordSelectedProject.Project
    )
);
Set(
    gblProjectHeaderData,
    {
        ID: gblRecordSelectedProject.Project,
        Name: gblRecordSelectedProject.'Project Name',
        Technology: Text(gblRecordSelectedProject.Technology),
        Capacity: gblRecordSelectedProject.'Plant WTG Capacity [MW]',
        Status: Text(gblRecordSelectedProject.'Cluster State'.Name),
        Approval: Text(gblRecordSelectedProject.'Approval States')
    }
);
Patch(
    colMapLocation,
    {ID: 1},
    {
        Latitude: gblRecordSelectedProject.Latitude,
        Longitude: gblRecordSelectedProject.Longitude
    }
);
UpdateContext(
    {
        locChangedLatitude: gblRecordSelectedProject.Latitude,
        locChangedLongitude: gblRecordSelectedProject.Longitude,
        locChangedLatitude2: gblRecordSelectedProject.Latitude,
        locChangedLongitude2: gblRecordSelectedProject.Longitude,
        locNeedShareholdingEntitiesUpdate: false,
        locNeedPlantCostsRecalculation: false,
        locGeneralDataIsSavingDialogVisible: false,
        locGeneralDataSavingDialogText: Blank(),
        locIsGeneralFormDirty: false,
        locTaxFactorPercentage: gblRecordSelectedProject.'Tax Factor [%]',
        locMunicipality: gblRecordSelectedProject.Municipality
    }
);
//Select(btn_GeneralData_DisplayProject_Body_Buttons_Reset);

With(
    {
        varAutoSkippedComment: "Automatically completed because this project starts at a later cluster."
    },
    With(
        {
            varStatesWithClusterNo: AddColumns(
                Filter(
                    'Project States' As PS,
                    PS.'Is Visible On Checklist' = true &&
                    (
                        PS.Name = "Draft" ||
                        PS.Name = "Cluster 1" ||
                        PS.Name = "Cluster 2" ||
                        PS.Name = "Cluster 3" ||
                        PS.Name = "Cluster 4" ||
                        PS.Name = "Cluster 5" ||
                        PS.Name = "Cluster 6"
                    )
                ) As PS,
                ClusterNo,
                Switch(
                    PS.Name,
                    "Draft", 0,
                    "Cluster 1", 1,
                    "Cluster 2", 2,
                    "Cluster 3", 3,
                    "Cluster 4", 4,
                    "Cluster 5", 5,
                    "Cluster 6", 6,
                    999
                )
            )
        },
        With(
            {
                varDraftState: LookUp(
                    varStatesWithClusterNo,
                    Name = "Draft"
                ),
                varOldGateSourceState: LookUp(
                    varStatesWithClusterNo,
                    ClusterNo = If(
                        locGeneralSaveOldStartClusterNo <= 1,
                        0,
                        locGeneralSaveOldStartClusterNo - 1
                    )
                ),
                varOldDraftApprovalNextState: LookUp(
                    varStatesWithClusterNo,
                    ClusterNo = If(
                        locGeneralSaveOldStartClusterNo = 0,
                        1,
                        locGeneralSaveOldStartClusterNo
                    )
                )
            },
            With(
                {
                    varDraftTracking: LookUp(
                        'Project State Trackings',
                        Project.Project = gblRecordSelectedProject.Project &&
                        'Cluster State'.'Project State' = varDraftState.'Project State'
                    ),
                    varOldGateRecord: LookUp(
                        'Project Default Approvals',
                        Not(IsBlank('Cluster State')) &&
                        'Cluster State'.'Project State' = varOldGateSourceState.'Project State'
                    )
                },

                // =====================================================
                // 1. If old Draft approval is still running, cancel it
                // =====================================================
                If(
                    And(
                        Not(IsBlank(varDraftTracking)),
                        Not(IsBlank(varDraftTracking.FlowRunId)),
                        varDraftTracking.'Approval Cluster State' = 'Approval Cluster States'.'In Progress'
                    ),
                    IfError(
                        PerformRequestofGateApprovalCancellation.Run(
                            gblProjectManagmentAppID,
                            JSON(
                                {
                                    ProjectGuid: gblRecordSelectedProject.Project,
                                    ProjectId: gblRecordSelectedProject.'Project ID',
                                    ProjectName: gblRecordSelectedProject.'Project Name',
                                    StateGuid: varDraftState.'Project State',
                                    StateName: varDraftState.Name,
                                    StateTrackingGuid: varDraftTracking.'Project State Tracking',
                                    HasGate: Not(IsBlank(varOldGateRecord)),
                                    GateSettingsGuid: varOldGateRecord.'Project Default Approvals',
                                    PreviousClusterGuid: Blank(),
                                    NextClusterGuid: varOldDraftApprovalNextState.'Project State',
                                    PortfolioManager: Coalesce(
                                        varOldGateRecord.'Portfolio Manager'.Mail,
                                        ""
                                    ),
                                    FlowRunId: varDraftTracking.FlowRunId,
                                    FlowApprovalId: varDraftTracking.FlowApprovalId
                                }
                            )
                        ),
                        false
                    )
                );

                // =====================================================
                // 2. Force Project Cluster State back to Draft
                // =====================================================
                Set(
                    gblRecordSelectedProject,
                    Patch(
                        Projects,
                        gblRecordSelectedProject,
                        {
                            'Cluster State': LookUp(
                                'Project States',
                                'Project State' = varDraftState.'Project State'
                            ),
                            'Besitzer (Unternehmenseinheit)': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                        }
                    )
                );

                // =====================================================
                // 3. Rebuild tracking rows based on NEW Start Cluster
                //
                // Draft          = In Progress
                // Skipped rows   = Completed
                // Start + later  = Not Started
                // =====================================================
                ForAll(
                    varStatesWithClusterNo As StateRow,
                    With(
                        {
                            varExistingTracking: LookUp(
                                'Project State Trackings',
                                Project.Project = gblRecordSelectedProject.Project &&
                                'Cluster State'.'Project State' = StateRow.'Project State'
                            ),
                            varTargetApprovalState: If(
                                StateRow.Name = "Draft",
                                'Approval Cluster States'.'In Progress',
                                If(
                                    StateRow.ClusterNo > 0 &&
                                    StateRow.ClusterNo < locGeneralSaveNewStartClusterNo,
                                    'Approval Cluster States'.Completed,
                                    'Approval Cluster States'.'Not Started'
                                )
                            ),
                            varTargetComment: If(
                                StateRow.ClusterNo > 0 &&
                                StateRow.ClusterNo < locGeneralSaveNewStartClusterNo,
                                varAutoSkippedComment,
                                Blank()
                            )
                        },
                        Patch(
                            'Project State Trackings',
                            Coalesce(
                                varExistingTracking,
                                Defaults('Project State Trackings')
                            ),
                            {
                                Project: gblRecordSelectedProject,
                                'Cluster State': LookUp(
                                    'Project States',
                                    'Project State' = StateRow.'Project State'
                                ),
                                'Approval Cluster State': varTargetApprovalState,
                                'Cluster Step State': Blank(),
                                'Approval Due Date': Blank(),
                                FlowRunId: Blank(),
                                FlowApprovalId: Blank(),
                                'Approval Comment': varTargetComment,
                                'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                            }
                        )
                    )
                )
            )
        )
    )
)
